script:
// Gold Rush Tycoon v16 — droppers fill your vault, you sweep it, you
// buy walls and weapons, and you raid other players' vaults.
Game.on('join', function (name) { Game.toast(name + ' joined the Gold Rush!'); });

var WON = false;
Game.on('collect', function (v, plot) {
  if (!WON && Game.money() >= 40000) {
    WON = true;
    Game.banner('GOLD TYCOON! You hit $40,000!');
  }
});
Game.on('buy', function (label) {
  if (label === 'FREE Dropper') Game.toast('Ore rides the belt into your vault. Step on the vault to sweep it!');
  if (label === 'Perimeter Walls') Game.toast('Walls up — harder to raid your vault.');
  if (label === 'MEGA Dropper') Game.banner('A MEGA DROPPER roars to life!');
  if (label === 'DIAMOND Dropper') Game.banner('DIAMOND DROPS! The mine sparkles.');
});
Game.on('zwave', function (n) { Game.toast(n + ' zombies rise in the battlefield!'); });

// ---------- ADMIN COMMANDS (type in chat) ----------
Game.on('cmd', function (text) {
  if (text.charAt(0) !== '/') return false;
  var p = text.slice(1).split(/\s+/);
  var c = p[0].toLowerCase();
  if (c === 'help') {
    Game.banner('/money N - /give item - /weapon item dmg - /pet radius dmg zap - /zombies N - /reset');
    return true;
  }
  if (c === 'money') { Game.addMoney(Math.round(+p[1] || 0)); Game.toast('Admin: money added'); return true; }
  if (c === 'give') {
    if (!p[1]) { Game.toast('Usage: /give item-id (see the cases)', true); return true; }
    Game.give(p[1]); Game.toast('Admin: gave ' + p[1]); return true;
  }
  if (c === 'weapon') {
    var d = Math.round(+p[2] || 0);
    if (!p[1] || !d) { Game.toast('Usage: /weapon item damage', true); return true; }
    Game.tuneItem(p[1], { damage: d, pvp: Math.round(d * 1.5) });
    Game.toast('Admin: ' + p[1] + ' -> ' + d + ' dmg'); return true;
  }
  if (c === 'pet') {
    var r = +p[1] || 0, pd = +p[2] || 0, z = +p[3] || 0;
    if (!r || !pd || !z) { Game.toast('Usage: /pet radius damage zapRange', true); return true; }
    Game.tuneItem('storm-pet', { radius: r, damage: pd, zapRange: z });
    Game.toast('Admin: pet -> ' + r + 'r ' + pd + 'd ' + z + 'z'); return true;
  }
  if (c === 'zombies') { var n = Game.zombies(Math.min(8, +p[1] || 4), 0, 0, 40); Game.toast('Admin: ' + n + ' zombies'); return true; }
  if (c === 'reset') { Game.resetWorld(); return true; }
  return false;
});
